import { CommonModule } from '@angular/common';
import { booleanAttribute, Component, HostBinding, Input } from '@angular/core';
import { VariablesService } from '../../../core/services/variables.service';

@Component({
  selector: 'btn',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './button.component.html',
  styleUrl: './button.component.scss'
})
export class ButtonComponent {
  @Input() mode = 'solid';
  @Input() text = '';
  @Input() disabled = false;
  @Input({ transform: booleanAttribute }) square = false;
  @Input() addcls = '';
  @Input() isloading = false;
  @Input() loader = '';
  @Input({ transform: booleanAttribute }) issmall = false;
  @Input({ transform: booleanAttribute }) active = false;
  @Input({ transform: booleanAttribute }) noborder = false;

  @HostBinding('class.disabledbtn') get isDisabledClass(): boolean {
    return this.disabled;
  }

  constructor(private readonly vs: VariablesService) {}

  get buttonClasses(): string {
    const variants = this.vs.btnvarnt as Record<string, string>;
    const modeClass = variants[this.mode] ?? '';
    const activeClass = this.active ? variants['active'] ?? '' : '';
    const noBorderClass = this.noborder ? variants['noborder'] ?? '' : '';
    return `${this.addcls} ${activeClass} ${noBorderClass} ${modeClass}`.trim();
  }
}
